#!/usr/bin/env bash
# recipes/crate-luajit-src--210-5-5/build.sh -- stage the luajit-src 210.5.5+f2336c4 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/luajit-src-210.5.5+f2336c4"
